/* HEXA BATTLEGROUNDS setup — PART 63 OF 83. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-bomb-18', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Black, Green, Yellow, White.\nSerial number: OM29A3.  LED: RED.","game":{"type":"bomb","wires":["black","green","yellow","white"],"serial":"OM29A3","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the LED is BLUE and the first wire is YELLOW, cut the LAST wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'black,green,yellow,white · OM29A3 · red → otherwise → first wire → wire 1', null, 25, 'published'), ('mission-bomb-19', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Green, White, Blue, White, Blue.\nSerial number: HX99A1.  LED: RED.","game":{"type":"bomb","wires":["green","white","blue","white","blue"],"serial":"HX99A1","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are no RED wires at all, cut the wire just ABOVE the last one — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["4"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'green,white,blue,white,blue · HX99A1 · red → override: If there are no RED wires at all, cut the wire just ABOVE the last one — ignore the manual. → wire 4', null, 25, 'published'), ('mission-bomb-20', 'bomb', 'mission', 'Bomb Defusal', 'game', 2, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Yellow, Red, Red, Red, White, White.\nSerial number: TN27Z4.  LED: RED.","game":{"type":"bomb","wires":["yellow","red","red","red","white","white"],"serial":"TN27Z4","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["5"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'yellow,red,red,red,white,white · TN27Z4 · red → override: If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual. → wire 5', null, 25, 'published'), ('mission-bomb-21', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Green, Black, Blue, Green.\nSerial number: HX36A7.  LED: RED.","game":{"type":"bomb","wires":["green","black","blue","green"],"serial":"HX36A7","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the serial number contains the digit 7, cut the THIRD wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["3"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'green,black,blue,green · HX36A7 · red → override: If the serial number contains the digit 7, cut the THIRD wire — ignore the manual. → wire 3', null, 25, 'published'), ('mission-bomb-22', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Green, Black, Green, Black.\nSerial number: HX51Q6.  LED: RED.","game":{"type":"bomb","wires":["green","black","green","black"],"serial":"HX51Q6","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are exactly two BLACK wires, cut the FIRST black wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["2"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'green,black,green,black · HX51Q6 · red → override: If there are exactly two BLACK wires, cut the FIRST black wire — ignore the manual. → wire 2', null, 25, 'published'), ('mission-bomb-23', 'bomb', 'mission', 'Bomb Defusal', 'game', 2, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Black, Yellow, Blue, Black.\nSerial number: TN44Q9.  LED: GREEN.","game":{"type":"bomb","wires":["black","yellow","blue","black"],"serial":"TN44Q9","led":"green"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the LED is BLUE and the first wire is YELLOW, cut the LAST wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["3"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'black,yellow,blue,black · TN44Q9 · green → serial ends odd and there is blue → first blue → wire 3', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
